<?php
namespace App\Http\Controllers\Tenant;
use App\Http\Controllers\Controller;use App\Tenancy\TenantContext;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class StaffController extends Controller{
 public function index(TenantContext $ctx){$t=$ctx->requireTenant();return view('tenant.manage.staff',['tenant'=>$t,'staff'=>$t->users()->wherePivotIn('role',['owner','admin','manager','staff','checkin'])->get(),'invites'=>DB::table('tenant_invitations')->where('tenant_id',$t->id)->whereNull('accepted_at')->latest()->get()]);}
 public function invite(Request $r,TenantContext $ctx){$t=$ctx->requireTenant();$d=$r->validate(['email'=>'required|email|max:190','role'=>'required|in:admin,manager,staff,checkin']);$token=bin2hex(random_bytes(32));DB::table('tenant_invitations')->insert(['tenant_id'=>$t->id,'email'=>strtolower($d['email']),'role'=>$d['role'],'token'=>$token,'expires_at'=>now()->addDays(7),'created_at'=>now(),'updated_at'=>now()]);return back()->with('status','Invite created: '.url('/staff-invite/'.$token));}
 public function remove(Request $r,TenantContext $ctx,int $user){$t=$ctx->requireTenant();$membership=$t->users()->where('users.id',$user)->first()?->pivot;abort_unless($membership&&$membership->role!=='owner',422);$t->users()->detach($user);return back()->with('status','Staff access removed.');}
 public function accept(Request $r,string $token){$invite=DB::table('tenant_invitations')->where('token',$token)->whereNull('accepted_at')->first();abort_unless($invite&&now()->lte($invite->expires_at),404);abort_unless(strtolower($r->user()->email)===strtolower($invite->email),403,'Sign in with the invited email address.');DB::transaction(function()use($invite,$r){DB::table('tenant_users')->updateOrInsert(['tenant_id'=>$invite->tenant_id,'user_id'=>$r->user()->id],['role'=>$invite->role,'status'=>'active','created_at'=>now(),'updated_at'=>now()]);DB::table('tenant_invitations')->where('id',$invite->id)->update(['accepted_at'=>now(),'updated_at'=>now()]);});$domain=DB::table('tenant_domains')->where('tenant_id',$invite->tenant_id)->where('is_primary',1)->value('domain');return redirect('https://'.$domain.'/manage')->with('status','Staff invitation accepted.');}
}